//! ⚖️ Exact original diagnostics match the canonical independent JSON view and actual caller receipts.
use super::*;
use semio_framework_value::ToValue;
use semio_framework_value::retained_clone::RetainedCloneGrant;
use semio_framework_job::{OperationId,Generation,StepBudget,root_cancel_token};
fn fault_bytes(fault:&Fault)->usize{
 let scope=&fault.scope;let mut bytes=std::mem::size_of::<FaultScope>()+fault.code.0.capacity()+fault.message.capacity()+fault.causes.capacity()*std::mem::size_of::<FaultCause>();
 for text in [&scope.plugin_id,&scope.app_id,&scope.instance_id,&scope.module,&scope.body_key]{bytes+=text.as_ref().map_or(0,String::capacity)}
 for cause in &fault.causes{bytes+=cause.message.capacity()+cause.code.as_ref().map_or(0,|code|code.0.capacity())}
 if let Some(params)=&fault.params{bytes+=std::mem::size_of::<FaultParams>()+params.0.capacity()*std::mem::size_of::<(String,String)>();for(key,value)in &params.0{bytes+=key.capacity()+value.capacity()}}bytes
}
/// 🧾️ Moving the original inline header preserves the same physical Fault scope identity throughout output.
#[test]
fn original_extension_invoke_fault_reply_preserves_source_system_receipts_and_canonical_wire(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();
 for copy in corpus["failureCopyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
  let mut fault=Fault::new(FaultOrigin::Extension,"extension.original","源🌊 diagnostic");fault.scope.plugin_id=Some("original-plugin".into());fault.scope.body_key=Some("body-71".into());fault.span=Some(TextSpan{line:3,column:7,length:11});fault.causes=vec![FaultCause{retained_progress:None,message:"original nested cause".into(),code:Some("extension.child".into())}];fault.params=Some(Box::new(FaultParams(vec![("count".into(),"7".into())])));
  let expected:serde_json::Value=fault.to_value().into();let original=fault_bytes(&fault);let address=fault.scope.as_ref()as *const FaultScope as usize;let cause=ExtensionInvocationCause::Fault(fault);
  let(mut owner,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||RetainedExtensionFaultReply::new(cause));assert_eq!((birth.requested_bytes,birth.released_bytes),(0,0));assert_eq!(owner.cause.as_ref().unwrap().projection_identity(),address);
  let cancel=root_cancel_token();let mut sequence=0;let mut born=0;let mut freed=0;let mut output=None;
  for turn in 0..100000{
   let demand=owner.demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)};
   let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);
   let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut cx));let result=result.unwrap();let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;
   if let Some(source)=owner.cause.as_ref(){assert_eq!(source.projection_identity(),address)}
   if result.is_some(){output=result;break}assert!(turn<99999,"original fault output stalled copy={copy} phase={} demand={demand:?}",owner.phase);
  }
  let output=output.unwrap();assert!(owner.terminal_is_empty());assert_eq!(original+born,freed+output.capacity());let decoded=semio_framework_os_kernel::os_pack::pack_rt::decode_wire_value(&output).unwrap();let produced:serde_json::Value=decoded.into();assert_eq!(produced,expected);
  let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  eprintln!("[DEBUG] original fault output copy={copy} sameSource=true canonicalWire=true born={born} freed={freed} outputCapacity={} Drop0=true",output.capacity());
 }
}

/// 🍂️ Every original failure prefix survives cancellation until its whole actual backing closes.
#[test]
fn original_extension_invoke_fault_reply_cancel_closes_original_prefix_and_output(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();
 for copy in corpus["failureCopyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){for stop in corpus["cancelCuts"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
  let fault=Fault::new(FaultOrigin::Extension,"extension.original-cancel","original cancellation 源🌊");let original=fault_bytes(&fault);let mut owner=RetainedExtensionFaultReply::new(ExtensionInvocationCause::Fault(fault));let cancel=root_cancel_token();let mut sequence=0;let mut born=0;let mut freed=0;
  for turn in 0..100000{if turn==stop{owner.begin_close();cancel.cancel_now()}let demand=owner.demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)};let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut cx));assert!(result.unwrap().is_none());let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;if owner.terminal_is_empty(){break}assert!(turn<99999,"original cancellation failed copy={copy} stop={stop} phase={} demand={demand:?}",owner.phase)}
  assert!(owner.terminal_is_empty());assert_eq!(original+born,freed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] original fault cancel copy={copy} stop={stop} actualSystemConservation=true Drop0=true");
 }}
}

/// 📬️ Every inference cause retains its original owned fields through canonical fault output.
#[test]
fn original_inference_gateway_failure_all_owned_causes(){
 for copy in [1,3,64]{for case in 0..8{
  let value=match case{0=>crate::ArtifactInferenceGatewayFailure::Native(ValueError::new(ValueRefusalKind::InvalidValue,"same native 源")),1=>crate::ArtifactInferenceGatewayFailure::Json(semio_framework_pack_json::JsonError::DuplicateMember{name:"same member 源".into(),offset:11}),2=>crate::ArtifactInferenceGatewayFailure::Execution(crate::ArtifactInferenceExecutionError::new("inference.original","same execution 源")),3=>crate::ArtifactInferenceGatewayFailure::Literal("same literal source"),4=>crate::ArtifactInferenceGatewayFailure::Json(semio_framework_pack_json::JsonError::UnexpectedByte{found:255,offset:83}),5=>crate::ArtifactInferenceGatewayFailure::Json(semio_framework_pack_json::JsonError::ControlCharacterInString{byte:31,offset:97}),6=>crate::ArtifactInferenceGatewayFailure::Json(semio_framework_pack_json::JsonError::MaxDepthExceeded(u32::MAX)),_=>crate::ArtifactInferenceGatewayFailure::Json(semio_framework_pack_json::JsonError::TrailingData(usize::MAX))};
  let(code,message,progress)=value.fault_wire_fields();let mut expected=serde_json::json!({"origin":"plugin","code":code,"severity":"error","message":message,"scope":{},"retainedProgress":{"copiedItems":progress.copied_items,"copiedBytes":progress.copied_bytes,"retainedCapacityBytes":progress.retained_capacity_bytes,"releasedBytes":progress.released_bytes},"retryable":false});if let Some(source)=value.fault_source(){let mut fields=serde_json::Map::new();if let Some(value)=source.offset{fields.insert("offset".into(),value.into());}if let Some(value)=source.byte{fields.insert("byte".into(),value.into());}if let Some(value)=source.depth{fields.insert("depth".into(),value.into());}expected["source"]=serde_json::Value::Object(fields);}let address=value.source_identity();
  let(mut owner,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||RetainedExtensionFaultReply::new(ExtensionInvocationCause::Inference(value.into())));assert_eq!((birth.requested_bytes,birth.released_bytes),(0,0));let cancel=root_cancel_token();let mut sequence=0;let mut output=None;
  for turn in 0..100000{let demand=owner.demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)};let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut cx));let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));if let Some(source)=owner.cause.as_ref(){assert_eq!(source.projection_identity(),address);if let ExtensionInvocationCause::Inference(crate::ArtifactInferenceGatewayRefusal{primary:crate::ArtifactInferenceGatewayFailure::Json(semio_framework_pack_json::JsonError::DuplicateMember{name,offset}),..})=source{assert_eq!((name.as_str(),*offset),("same member 源",11));}}if let Some(bytes)=result.unwrap(){output=Some(bytes);break}assert!(turn<99999,"gateway cause case={case} copy={copy} phase={} demand={demand:?}",owner.phase);}
  assert!(owner.terminal_is_empty());let decoded:serde_json::Value=semio_framework_os_kernel::os_pack::pack_rt::decode_wire_value(&output.unwrap()).unwrap().into();assert_eq!(decoded,expected);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Original gateway failure case={case} copy={copy} retains source and owned JSON detail; actual System receipt and canonical Serde view; terminalDrop0");
 }}
}

/// 🪢️ Original paired failures preserve both source allocations and independent metadata through paid publication.
#[test]
fn original_extension_job_failure_pair_preserves_both_canonical_receipts(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🔨️modules/🧵️job/⚠️failure/🧪️tests/🧫️fixtures/🔣️.json" )).unwrap();let wire=&corpus["wire"];
 let make=|row:&serde_json::Value|{let r=&row["retainedProgress"];ValueError::new(semio_framework_value::ValueRefusalKind::from_wire(row["kind"].as_str().unwrap()).unwrap(),row["message"].as_str().unwrap()).with_retained_progress(RetainedCloneProgress{copied_items:r["copiedItems"].as_u64().unwrap()as usize,copied_bytes:r["copiedBytes"].as_u64().unwrap()as usize,retained_capacity_bytes:r["retainedCapacityBytes"].as_u64().unwrap()as usize,released_bytes:r["releasedBytes"].as_u64().unwrap()as usize})};
 for copy in corpus["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
  let primary=make(&wire["primary"]);let secondary=make(&wire["receiptRefusal"]);let pointers=(primary.message.as_ptr(),secondary.message.as_ptr());let original=primary.message.len()+secondary.message.len();let mut owner=RetainedExtensionFaultReply::new(ExtensionInvocationCause::Turn(OriginalTurnFailure{primary:primary.into(),receipt_refusal:Some(secondary),context_refusal:None}));let cancel=root_cancel_token();let mut sequence=0;let(mut born,mut freed)=(0,0);let mut output=None;
  for turn in 0..100000{let demand=owner.demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)};
   if turn==0{for budget in [StepBudget::new(0,u64::MAX,grant),StepBudget::new(1,0,grant)]{let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),budget,cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut cx));assert!(result.unwrap().is_none());assert_eq!(cx.retained_progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}}
   let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut cx));let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;
   if let Some(ExtensionInvocationCause::Turn(pair))=owner.cause.as_ref(){assert_eq!((pair.primary.message().as_ptr(),pair.receipt_refusal.as_ref().unwrap().message.as_ptr()),pointers)}if let Some(bytes)=result.unwrap(){output=Some(bytes);break}assert!(turn<99999,"pair output stalled copy={copy} phase={} demand={demand:?}",owner.phase);
  }
  let output=output.unwrap();assert!(owner.terminal_is_empty());assert_eq!(original+born,freed+output.capacity());let produced:serde_json::Value=semio_framework_os_kernel::os_pack::pack_rt::decode_wire_value(&output).unwrap().into();assert_eq!(produced["message"],wire["primary"]["message"]);assert_eq!(produced["code"],wire["primary"]["kind"]);assert_eq!(produced["retainedProgress"],wire["primary"]["retainedProgress"]);assert_eq!(produced["causes"],serde_json::json!([{"message":wire["receiptRefusal"]["message"],"code":wire["receiptRefusal"]["kind"],"retainedProgress":wire["receiptRefusal"]["retainedProgress"]}]));let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] original job paired fault copy={copy} sameSources=true distinctReceipts=true canonicalSerde=true SystemConservation=true Drop0=true");
 }
}

#[test]
fn original_extension_context_failure_preserves_complete_canonical_wire(){
 use semio_framework_value::FromValue;
 use crate::app_testing::OriginalFixtureCaller;
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🔨️modules/🧵️job/⚠️failure/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let wire=&corpus["contextWire"];let maximum_turns=OriginalFixtureCaller::maximum_turns();
 let make=|row:&serde_json::Value|{let p=&row["retainedProgress"];ValueError::new(ValueRefusalKind::from_wire(row["kind"].as_str().unwrap()).unwrap(),row["message"].as_str().unwrap()).with_retained_progress(RetainedCloneProgress{copied_items:p["copiedItems"].as_u64().unwrap()as usize,copied_bytes:p["copiedBytes"].as_u64().unwrap()as usize,retained_capacity_bytes:p["retainedCapacityBytes"].as_u64().unwrap()as usize,released_bytes:p["releasedBytes"].as_u64().unwrap()as usize})};
 let delta=|before:RetainedCloneProgress,after:RetainedCloneProgress|RetainedCloneProgress{copied_items:after.copied_items.checked_sub(before.copied_items).unwrap(),copied_bytes:after.copied_bytes.checked_sub(before.copied_bytes).unwrap(),retained_capacity_bytes:after.retained_capacity_bytes.checked_sub(before.retained_capacity_bytes).unwrap(),released_bytes:after.released_bytes.checked_sub(before.released_bytes).unwrap()};
 let mut expected=wire["primary"].clone();for name in ["receiptRefusal","contextRefusal"]{let row=&wire[name];expected["causes"].as_array_mut().unwrap().push(serde_json::json!({"message":row["message"],"code":row["kind"],"retainedProgress":row["retainedProgress"]}));}
 for copy in [1,3,64]{
  let(mut caller,caller_birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OriginalFixtureCaller::admit().unwrap());let mut cx=caller.context();let stock=cx.retained_grant();let identity=(cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity());let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..stock};
  let((cause,pointers),initial)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let primary=Fault::from_value(serde_json::from_value(wire["primary"].clone()).unwrap()).unwrap();let receipt=make(&wire["receiptRefusal"]);let context=make(&wire["contextRefusal"]);let pointers=(primary.message.as_ptr(),primary.scope.as_ref()as *const _,receipt.message.as_ptr(),context.message.as_ptr());(ExtensionInvocationCause::Turn(OriginalTurnFailure{primary:primary.into(),receipt_refusal:Some(receipt),context_refusal:Some(context)}),pointers)});
  let(mut owner,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||RetainedExtensionFaultReply::new(cause));assert_eq!((birth.requested_bytes,birth.released_bytes),(0,0));let(mut born,mut freed)=(initial.requested_bytes,initial.released_bytes);let mut output=None;
  for denied in [RetainedCloneGrant{maximum_items:0,..loan},RetainedCloneGrant{maximum_depth:0,..loan}]{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(denied,|same|{assert!(owner.advance(same)?.is_none());Ok(())}));result.unwrap();assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  let mut slots=[Some(owner),None];let mut slot=0;
  for turn in 0..maximum_turns{
   let mut owner=slots[slot].take().unwrap();let source=owner.cause.as_ref().map(|cause|cause.projection_identity());
   let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|same|{output=owner.advance(same)?;Ok(())}));result.unwrap();let progress=delta(before,cx.retained_progress());assert!(progress.fits(loan));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(fuel-cx.fuel_remaining(),1);born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!((cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity()),identity);
   if let Some(ExtensionInvocationCause::Turn(held))=owner.cause.as_ref(){let primary=held.primary_fault().unwrap();assert_eq!((primary.message.as_ptr(),primary.scope.as_ref()as *const _,held.receipt_refusal.as_ref().unwrap().message.as_ptr(),held.context_refusal.as_ref().unwrap().message.as_ptr()),pointers);}
   if let Some(cause)=owner.cause.as_ref(){assert_eq!(Some(cause.projection_identity()),source)}let phase=owner.phase;
   let(_,moved)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{slot=1-slot;slots[slot]=Some(owner)});assert_eq!((moved.requested_bytes,moved.released_bytes),(0,0));
   if output.is_some(){break}assert!(turn+1<maximum_turns,"original context diagnostic stalled copy={copy} phase={phase}");
  }
  let owner=slots[slot].take().unwrap();let output=output.unwrap();assert!(owner.terminal_is_empty());assert_eq!(born,freed+output.capacity());let observed:serde_json::Value=semio_framework_os_kernel::os_pack::pack_rt::decode_wire_value(&output).unwrap().into();assert_eq!(observed,expected);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  let before=cx.retained_progress();let(mut output,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert!(!cx.should_yield());cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()}).unwrap();cx.consume_fuel(1);ControlledRetirement::new(output).unwrap()});assert_eq!((birth.requested_bytes,birth.released_bytes),(0,0));assert_eq!(delta(before,cx.retained_progress()).copied_items,1);
  for turn in 0..maximum_turns{if output.terminal_is_empty(){break}let demand=output.selected_demand(copy).unwrap();let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|same|{semio_framework_job::close_original_retained_step(same,demand,|grant|output.step(grant))?;Ok(())}));result.unwrap();let progress=delta(before,cx.retained_progress());assert!(progress.fits(loan));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(turn+1<maximum_turns)}
  assert_eq!(born,freed);assert!(output.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(output));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let fuel=cx.fuel_remaining();drop(cx);let(_,caller_close)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.retire(fuel).unwrap());assert_eq!(caller_birth.requested_bytes+caller_close.requested_bytes,caller_birth.released_bytes+caller_close.released_bytes);
 }eprintln!("[DEBUG] complete diagnostic and receipt/context canonical wire; same finite caller and source pointers; copies1_3_64; actual cumulative receipts, full paid output and caller close");
}
